ommission":"surf-school / lesson referral"},{"name":"Bocas Town Caribbean nightlife","si_tag":"expedition","tier":"essential","source":"https://www.takeyourbackpack.com/backpacking-in-panama/visit-bocas-del-toro/","hook":"the stilted harbor town''s bars, over-water clubs, and reggae/soca scene","si":"expedition","blurb":"the stilted harbor town''s bars, over-water clubs, and reggae/soca scene","commission":"F&B / experience add-on (drives room-nights)"}],"faq":null,"seo":{"meta_title":"Bocas del Toro, Panama Travel Guide 2026 — Islands, Reefs, Overwater Villas | TravelWell","search_language":"es-PA","jsonld_type":"TouristDestination","author_byline":"By David McCallister — commercial pilot, 56 countries","freshness":"2026-07-07","local_keywords":["Bocas del Toro qué hacer","Cayos Zapatillas","Isla Bastimentos","Bocas del Toro cuándo ir","playa Estrella Bocas","surf en Bocas del Toro","tour bioluminiscencia Bocas","villas sobre el agua Panamá"],"hreflang":["en","es-PA"]},"booking":null,"si_checklist_25":null,"sis_present":null,"ultra":[{"name":"Nayara Bocas del Toro","island":"Frangipani","model":"luxury-resort / Virtuoso-style preferred","tier":"luxury","mor":false,"note":"CNT #1 Central America; adults-only overwater"},{"name":"Sweet Bocas","model":"whole-estate MoR buyout","tier":"$$$$$","mor":true,"note":"AD-featured 9-BR teak overwater private-island villa; ~26 adults; $10,500/night base"},{"name":"Red Frog Beach Island Resort","island":"Bastimentos","model":"resort + villa commission","tier":"$$$","mor":"villa inventory via Red Frog Property"},{"name":"Isla Palenque","model":"luxury private-island (Pacific Gulf of Chiriquí — NOT Bocas)","tier":"luxury","mor":false,"note":"two-coast Panama add-on, not a Bocas jewel"}],"source_verified":null,"hero":{"query":"Bocas del Toro, Panama, Panama"},"geo":{"lat":9.3402,"lng":-82.2417}}'::jsonb, 11),
  ('bogota-colombia', '10S', 'Bogotá & The Andes, Colombia', 'Colombia', 'Andean capital, paramo on its doorstep', 'live', 'verified', 'venice', 'Bogotá & The Andes', '{"romance","adventure","culture","culinary"}', '{}', '{"essential","premier","luxury","ultra"}', null, null, '{"key_facts":["Bogotá sits at ~2,640 m (8,660 ft) — one of the highest capital cities on earth; expect mild soroche (altitude effects) for 24–48 hrs on arrival.","The Gold Museum (Museo del Oro) holds ~55,000 pre-Columbian gold pieces, incl. the Muisca raft of the El Dorado legend.","Monserrate rises to 3,152 m over the city, reached by funicular, cable car or a steep daytime walk, with the Basilica at the summit.","Zipaquirá Salt Cathedral is a cathedral carved inside a working salt mine ~1.5–2 hrs from the city; Villa de Leyva has Colombia''s largest cobbled plaza (14,000 m²) and a Cretaceous fossil valley.","Bogotá''s driest, clearest windows are Dec–Mar and Jul–Aug; the biennial Ibero-American Theatre Festival returns August 2026."],"safety":{"emergency":"123","hospital":"Bogotá top private clinics (stabilization); serious cases route to US medical evacuation — evac-grade insurance advised","book_enabled":true,"bin":"BOOK WITH WARNING","risk_codes":["C","T","U","K","N"],"risk_code_meanings":{"C":"Crime — violent crime (murder, assault, robbery), drugging (scopolamine/''devil''s breath''), extortion, express kidnapping occur throughout Colombia incl. cities","T":"Terrorism — attacks possible with little/no warning; car bombs, grenades, IEDs, drones","U":"Unrest — demonstrations can shut roads and turn violent","K":"Kidnapping or Hostage-Taking — kidnapping-for-ransom reported","N":"Natural Disaster — earthquake, landslide (advisory names Bogotá for landslide risk)"},"named_danger":["Arauca","Cauca excl Popayán","Valle del Cauca excl Cali","Norte de Santander","Venezuela border ~10km"],"bogota_in_named_danger":false,"consent_flow":{"bin":"BOOK WITH WARNING","disclosure_required":true,"renders":"full verbatim live US State Dept advisory for Colombia (level + reason + named-danger areas + complete ''If you decide to travel'' guidance, pulled live) + traveler acknowledgment","wording_status":"hook set only — final consent language PENDING compliance-attorney sign-off"},"air_access_verified":"BOG (El Dorado Intl) — direct international incl. major US, EU and LatAm gateways; Colombia''s primary hub","altitude_m":2640,"altitude_note":"~2,640 m — mild AMS possible 24–48 hrs; Monserrate 3,152 m and páramo hikes 3,200 m+ add load","water":"Bogotá tap generally potable (meets WHO standards per EAAB/Ministry of Health); caveat aging plumbing in older buildings — bottled is conservative default","disease_note":"dengue LOW at altitude (vector scarce above ~1,800 m); rises for low-altitude excursions","scopolamine_caution":"''devil''s breath''/burundanga drugging — colourless/tasteless; Bogotá hotspot (1,409 cases 2023, Chapinero/Teusaquillo/Santa Fe); never accept drinks/food/tabs from strangers; dating-app method documented","personal_safety":"vetted taxi/ride-app only; no wealth display; zone discipline (La Candelaria daytime); do not resist a robbery"},"timing":{"peak":"Dec–Mar (dry, peak season) and Jul–Aug (dry + biennial Ibero-American Theatre Festival, even years)","inflection_curve_start":"early December (Christmas peak); August 2026 (Theatre Festival + dry season); Semana Santa (late Mar/early Apr)","fire_date":"mid-to-late November (Dec–Mar peak); ~mid-July (Aug festival/dry peak); ~early March (Semana Santa)","event_peaks":[{"event":"Ibero-American Theatre Festival","dates_2026":"August 2026 (biennial, even years)","note":"800+ productions from 40+ countries; stacks on dry season"},{"event":"Semana Santa (Holy Week)","dates":"late March / early April","note":"major domestic-travel pulse across the Andes"},{"event":"Christmas–New Year","dates":"Dec 20–Jan 6","note":"peak congestion + higher rates"}],"off_season_fill":"Apr–May and Oct–Nov (green/wetter shoulders, lower rates, thinner crowds)"},"jewels":[{"name":"Gold Museum (Museo del Oro)","si_tag":"culture","tier":"essential","source":"https://www.viator.com/Bogota-attractions/Gold-Museum/d4560-a6188","timing":"year-round","timing_type":"ALWAYS-ON","hook":"~55,000 pre-Columbian gold pieces, the Muisca raft of the El Dorado legend; free on Sundays","si":"culture","blurb":"~55,000 pre-Columbian gold pieces, the Muisca raft of the El Dorado legend; free on Sundays","when":"year-round","commission":"city-tour affiliate; entry non-comm pass-through"},{"name":"Botero Museum","si_tag":"culture","tier":"essential","source":"https://theabroadguide.com/la-candelaria-mount-monserrate-and-the-gold-museum-in-one-day-in-bogota/","timing":"year-round","timing_type":"ALWAYS-ON","hook":"Fernando Botero''s donated collection, free entry, in La Candelaria","si":"culture","blurb":"Fernando Botero''s donated collection, free entry, in La Candelaria","when":"year-round","commission":"city-tour affiliate; free entry"},{"name":"La Candelaria colonial core + street art","si_tag":"culture","tier":"essential","source":"https://kittiaroundtheworld.com/things-to-do-in-la-candelaria-bogota-historic-centre/","timing":"Dec–Mar  and Jul–Aug","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"Plaza de Bolívar, 17th-c. Iglesia de Santa Clara, mural-covered lanes, the number-one neighbourhood in the city","si":"culture","blurb":"Plaza de Bolívar, 17th-c. Iglesia de Santa Clara, mural-covered lanes, the number-one neighbourhood in the city","when":"Dec–Mar  and Jul–Aug","commission":"walking-tour affiliate + boutique lodging"},{"name":"Zipaquirá Salt Cathedral","si_tag":"culture","tier":"essential","source":"https://thecolombianway.com/en/our-trips/day-trips/the-salt-cathedral-of-zipaquira/","timing":"year-round","timing_type":"ALWAYS-ON","hook":"a cathedral carved inside a working salt mine, glowing tunnels, carved crosses, an underground dome; ~1.5–2 hrs from Bogotá","si":"culture","blurb":"a cathedral carved inside a working salt mine, glowing tunnels, carved crosses, an underground dome; ~1.5–2 hrs from Bogotá","when":"year-round","commission":"day-trip DMC/operator; entry non-comm pass-through"},{"name":"Villa de Leyva (colonial plaza + fossils)","si_tag":"culture","tier":"premier","source":"https://en.wikipedia.org/wiki/Villa_de_Leyva","timing":"year-round","timing_type":"ALWAYS-ON","hook":"a whitewashed-town weekend around the great plaza, star-filled Andean skies, boutique fincas — the plateau''s romance run","si":"culture","blurb":"a whitewashed-town weekend around the great plaza, star-filled Andean skies, boutique fincas — the plateau''s romance run","when":"year-round","commission":"overnight DMC + colonial-house/finca villa MoR"},{"name":"Monserrate sunset (funicular/cable car)","si_tag":"romance","tier":"premier","source":"https://kittiaroundtheworld.com/things-to-do-in-la-candelaria-bogota-historic-centre/","timing":"Dec–Mar  and Jul–Aug","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"romance","when":"Dec–Mar  and Jul–Aug","commission":"hotel + funicular non-comm + DMC dining"},{"name":"Usaquén Sunday market + brunch","si_tag":"romance","tier":"essential","source":"https://www.tripadvisor.com/Attraction_Review-g294074-d1382992-Reviews-Mercado_de_las_Pulgas_de_Usaquen-Bogota.html","timing":"Dec–Mar  and Jul–Aug","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"the colonial northern district; every Sunday ~10:00–18:00 the streets fill with artisans, antiques, Colombian coffee and long brunches around the plaza","si":"romance","blurb":"the colonial northern district; every Sunday ~10:00–18:00 the streets fill with artisans, antiques, Colombian coffee and long brunches around the plaza","when":"Dec–Mar  and Jul–Aug","commission":"boutique-lodging + food-tour affiliate"},{"name":"Chingaza páramo hike","si_tag":"adventure","tier":"premier","source":"https://mytriptocolombia.com/hiking-chingaza-national-park-travel-guide/","timing":"Dec–Mar  and Jul–Aug","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"a magnificent páramo on Bogotá''s outskirts, frailejón moorland, glacial Siecha/Buitrago lagoons, guided day trips from the city","si":"adventure","blurb":"a magnificent páramo on Bogotá''s outskirts, frailejón moorland, glacial Siecha/Buitrago lagoons, guided day trips from the city","when":"Dec–Mar  and Jul–Aug","commission":"GEA DMC / licensed guide + park permit"},{"name":"Suesca rock-climbing","si_tag":"adventure","tier":"essential","source":"https://cuppatocopatravels.com/south-america/colombia/day-trips-weekend-breaks-from-bogota-2019/","timing":"Dec–Mar  and Jul–Aug","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"Colombia''s best climbing crag, ~1 hr north; sandstone canyon walls, beginner-to-advanced routes through local climbing schools","si":"adventure","blurb":"Colombia''s best climbing crag, ~1 hr north; sandstone canyon walls, beginner-to-advanced routes through local climbing schools","when":"Dec–Mar  and Jul–Aug","commission":"adventure DMC / climbing-school affiliate"},{"name":"Sumapaz páramo trek","si_tag":"adventure","tier":"premier","source":"https://www.lonelyplanet.com/articles/day-hikes-bogota-colombia","timing":"Dec–Mar  and Jul–Aug","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"the world''s largest páramo ecosystem, south of Bogotá; high-altitude moorland trekking, guided-only","si":"adventure","blurb":"the world''s largest páramo ecosystem, south of Bogotá; high-altitude moorland trekking, guided-only","when":"Dec–Mar  and Jul–Aug","commission":"GEA DMC / licensed guide (guided-only)"},{"name":"Paloquemao market + coffee","si_tag":"culinary","tier":"essential","source":"https://theabroadguide.com/la-candelaria-mount-monserrate-and-the-gold-museum-in-one-day-in-bogota/","timing":"Dec–Mar  and Jul–Aug","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"Bogotá''s great produce, flower and food market; early-morning fruit tastings and Colombian-coffee sourcing, a food-tour anchor","si":"culinary","blurb":"Bogotá''s great produce, flower and food market; early-morning fruit tastings and Colombian-coffee sourcing, a food-tour anchor","when":"Dec–Mar  and Jul–Aug","commission":"food-tour affiliate + DMC"},{"name":"Andrés Carne de Res (Chía)","si_tag":"culinary","tier":"premier","source":"https://www.tripadvisor.com/Restaurant_Review-g815502-d939879-Reviews-Andres_Carne_De_Res_Chia-Chia_Cundinamarca_Department.html","timing":"Dec–Mar  and Jul–Aug","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"the legendary maximalist restaurant ~40–60 min north of Bogotá — a labyrinth of over-the-top décor, live music and improv actors","si":"culinary","blurb":"the legendary maximalist restaurant ~40–60 min north of Bogotá — a labyrinth of over-the-top décor, live music and improv actors","when":"Dec–Mar  and Jul–Aug","commission":"DMC dining + vetted transport"}],"faq":[{"q":"What''s the most romantic thing to do in Bogotá?","a":"Ride the funicular or cable car up Monserrate at dusk for dinner at the summit restaurant, with the whole plateau of light beneath you — the city''s signature romance run. The ridge rises to 3,152 m (10,341 ft), and the Basilica crowns the summit.","source":"kittiaroundtheworld.com, 2026-07-07","si_tag":"romance"},{"q":"Can you go hiking near Bogotá?","a":"Yes — Andean páramo day-hikes start on the city''s doorstep and run guided. Chingaza páramo climbs from 2,600 to 4,000 m through frailejón moorland and glacial Siecha/Buitrago lagoons, while Suesca, about 1 hour north, is Colombia''s premier rock-climbing crag. Guided entry is the norm for the páramos.","source":"mytriptocolombia.com, 2026-07-07","si_tag":"adventure"},{"q":"What are the must-see museums and sights in Bogotá?","a":"The Gold Museum (Museo del Oro) is the headline — ~55,000 pre-Columbian gold pieces, including the Muisca raft of the El Dorado legend, and free on Sundays — alongside the Botero Museum and colonial La Candelaria. The core clusters in and above the historic centre.","source":"viator.com, 2026-07-07","si_tag":"culture"},{"q":"Where should you eat and drink around Bogotá?","a":"Andrés Carne de Res in Chía is the marquee night out — ranked #2 of 139 restaurants in Chía, a labyrinth of over-the-top décor, live music and improv actors, about 40–60 min north of the city. In town, Zona G is Bogotá''s dense \"gourmet zone.\"","source":"tripadvisor.com, 2026-07-07","si_tag":"culinary"},{"q":"What''s the real risk to plan for in Bogotá?","a":"Scopolamine (\"devil''s breath\" / burundanga) drugging is the headline traveler risk — a colourless, tasteless sedative used to rob or assault. Bogotá police recorded 1,409 cases in 2023 (+16% year-on-year), concentrated in Chapinero, Teusaquillo and Santa Fe, often via dating apps and offered drinks. Never accept drinks or tabs from strangers.","source":"thecitypaperbogota.com, 2026-07-07","si_tag":"safety"},{"q":"Is walking up Monserrate dangerous?","a":"Walk the Monserrate pilgrimage trail only in daylight and in groups — robberies have been reported on the path — or take the funicular or cable car instead. The summit stands at 3,152 m, so pace yourself for the altitude.","source":"kittiaroundtheworld.com, 2026-07-07","si_tag":"safety"}],"seo":{"meta_title":"Bogotá & The Andes, Colombia — Gold Museum, Monserrate, Zipaquirá & Villa de Leyva | TravelWell.World","jsonld_type":"TouristDestination","author_byline":"By David McCallister — commercial pilot, 56 countries","freshness":"2026-07-07","search_language":"es-CO","long_tail_en":["things to do in Bogotá Colombia","Gold Museum Bogotá guide","Monserrate funicular Bogotá","Zipaquirá Salt Cathedral day trip from Bogotá","Villa de Leyva from Bogotá","is Bogotá safe 2026","Bogotá altitude sickness"],"local_keywords":["qué hacer en Bogotá","Catedral de Sal Zipaquirá","Museo del Oro","Villa de Leyva","Monserrate Bogotá","hoteles de lujo Bogotá"],"hreflang":["en","es-CO"]},"booking":null,"si_checklist_25":null,"sis_present":["romance","adventure","culture","culinary"],"ultra":[{"name":"Four Seasons Hotel Casa Medina","type":"landmark 1946 building, Zona G, 62 rooms + 19 suites, Ministry-of-Culture monument","routing":"Fora/Virtuoso preferred","tier":"ultra"},{"name":"Four Seasons Hotel Bogotá","type":"second FS property, Zona T entertainment district, contemporary tower","routing":"Fora/Virtuoso preferred","tier":"ultra"},{"name":"Sofitel Bogotá Victoria Regia","type":"French-luxury prestige address, northern corridor","routing":"preferred-partner + host","tier":"luxury→ultra"},{"name":"W Bogotá (Zona T)","type":"Marriott lifestyle-luxury flagship, design-forward rooftop","routing":"preferred-partner + host","tier":"luxury"},{"name":"Click Clack Hotel","type":"design-forward boutique, northern corridor","routing":"preferred-partner + host","tier":"premium→luxury"},{"name":"Zona G / Chicó luxury-apartment buyouts","type":"serviced multi-bedroom apartments w/ concierge","routing":"MoR villa + host","tier":"premier"}],"source_verified":null,"hero":{"query":"Bogotá & The Andes, Colombia, Colombia"},"geo":{"lat":4.711,"lng":-74.0721}}'::jsonb, 12)
