  ('bonito-brazil', '10S', 'Bonito, Brazil', 'Brazil', 'Bonito', 'live', 'verified', 'mountainValley', 'Amazon, Pantanal & Iguaçu', '{"wildlife"}', '{}', '{"essential","comfort","premier"}', null, null, '{"key_facts":null,"safety":{"emergency":"190","advisory_level":"L2","advisory_why":"national crime + kidnapping risk indicator concentrated in cities, favelas, and Level-4 border zones — none describe interior Bonito","book_enabled":true,"bin":"freely bookable (L2)","consent_flow":false,"air_access_verified":true,"air_access":{"primary":"Bonito (BYO) — limited commercial service (~13 km from town)","gateway":"Campo Grande (CGR) + road transfer ~205 km / ~3–3.5 hrs"},"trauma_note":"rural interior; serious-trauma/evac route via Campo Grande (CGR); evacuation-coverage insurance essential for adventure stack","health_flag":"chikungunya outbreak reported in Mato Grosso do Sul — mosquito-bite prevention day and night","activity_flags":["river no-touch + no pre-entry sunscreen","cave/waterfall rappel technical + harness","cool water ~18–22°C neoprene"],"fcdo":{"posture":"AREA-RESTRICTED","quotes":[{"form":"against all but essential travel","text":"advises against all but essential travel Amazonas State FCDO advises against all but essential travel to the following river areas towards the west of Amazonas State: along the Amazonas (Amazon) River and its tributaries west of the town of Codajás and east of the town of Belém do Solimões in Amazonas State along any part of the Itaquaí River in Amazonas State along any part of the Japurá River or its tributaries in Amazonas State along the Rio Negro (Black River) and its tributaries north or west of the town of Barcelos in Amazonas State Find out more about why FCDO advises against travel ."},{"form":"against all but essential travel","text":"advises against all but essential travel: along the Amazonas (Amazon) River and its tributaries west of the town of Codajás and east of the town of Belém do Solimões in Amazonas State along any part of the Itaquaí River in Amazonas State along any part of the Japurá River or its tributaries in Amazonas State along the Rio Negro (Black River) and its tributaries north or west of the town of Barcelos in Amazonas State There are risks to travellers in river areas towards the west of Amazonas State, where Brazil shares borders with Colombia, Peru and Venezuela, due to criminal activity."}],"url":"https://www.gov.uk/foreign-travel-advice/brazil","read":"2026-08-19","page_updated":"2026-05-11T12:32:48+01:00"}},"timing":{"clarity_peak":"dry season ~Apr–Oct (core Jun–Sep)","crowd_price_peak":"December → Carnival","low_visibility_window":"Dec–Feb (rain raises rivers)","shoulder":"Mar–Jun (milder, fewer crowds)","inflection":"supply is physically day-capped; slots close weeks ahead in dry window","fire_date":"clarity-curve start − 1–2 weeks (late Mar–May for winter clarity trips; Oct–Nov ahead of Dec–Carnival)","off_season_fill":"dry low-season tail + wet-but-workable shoulder → flexible/budget/photography travelers","note":"attractions sell out, not just hotels — book the voucher itinerary"},"jewels":[{"name":"Rio da Prata float","si_tag":"expedition","tier":"comfort","source":"https://www.tripadvisor.com/ShowUserReviews-g303368-d1936985-r118728253-Rio_da_Prata-State_of_Mato_Grosso_do_Sul.html","si":"expedition","commission":"DMC/AOR → licensed-agency voucher"},{"name":"Rio Sucuri snorkel","si_tag":"expedition","tier":"essential","source":"https://www.aventuradobrasil.com/blog/bonito-brazils-natural-gem-of-crystal-clear-rivers-and-hidden-caves/","hook":"Described as one of the clearest rivers on Earth; emerald underwater gardens threaded with pearl-like oxygen bubbles. Gentler/shorter than Prata, superb clarity","si":"expedition","blurb":"Described as one of the clearest rivers on Earth; emerald underwater gardens threaded with pearl-like oxygen bubbles. Gentler/shorter than Prata, superb clarity","commission":"licensed-agency voucher via AOR"},{"name":"Abismo Anhumas rappel + underground-lake dive/snorkel","si_tag":"expedition","tier":"premier","source":"https://www.explore-share.com/trip/abismo-anhumas-abseiling-underground-lake-bonito/","hook":"72 m descent into a cavern lake with submerged limestone cones up to ~20 m; snorkel or scuba the lake; ~18°C water","si":"expedition","blurb":"72 m descent into a cavern lake with submerged limestone cones up to ~20 m; snorkel or scuba the lake; ~18°C water","commission":"AOR → operator via licensed agency"},{"name":"Boca da Onça waterfall circuit + 90m rappel","si_tag":"expedition","tier":"comfort","source":"https://www.bocadaonca.com.br/","hook":"Mato Grosso do Sul''s tallest waterfall; Brazil''s largest platform rappel; ~4,500 m trail, 8 waterfalls, natural pools","si":"expedition","blurb":"Mato Grosso do Sul''s tallest waterfall; Brazil''s largest platform rappel; ~4,500 m trail, 8 waterfalls, natural pools","commission":"AOR → licensed-agency voucher"},{"name":"Estância Mimosa waterfall trek","si_tag":"expedition","tier":"essential","source":"https://www.aventuradobrasil.com/blog/bonito-brazils-natural-gem-of-crystal-clear-rivers-and-hidden-caves/","hook":"Guided trail to a chain of waterfalls and swimming pools with strong flora/fauna viewing; also offers on-site lodging","si":"expedition","blurb":"Guided trail to a chain of waterfalls and swimming pools with strong flora/fauna viewing; also offers on-site lodging","commission":"AOR → voucher + room"},{"name":"Gruta do Lago Azul","si_tag":"expedition","tier":"essential","source":"https://en.wikipedia.org/wiki/Gruta_do_Lago_Azul_Natural_Monument","hook":"Guided-mandatory, no swimming. ~300-step descent; closed-toe shoes mandatory; no water access since 1992; the risk here is the stairs, not the water","si":"expedition","blurb":"Guided-mandatory, no swimming. ~300-step descent; closed-toe shoes mandatory; no water access since 1992; the risk here is the stairs, not the water","commission":"voucher via licensed agency; entry fee pass-through"},{"name":"Buraco das Araras (macaw sinkhole)","si_tag":"wildlife","tier":"essential","source":"https://en.wikipedia.org/wiki/Buraco_das_Araras_Private_Natural_Heritage_Reserve","hook":"Huge sandstone crater near Jardim; South America''s largest sinkhole; sanctuary for red-and-green macaws plus toucans/araçaris. Best at early morning / late afternoon","si":"wildlife","blurb":"Huge sandstone crater near Jardim; South America''s largest sinkhole; sanctuary for red-and-green macaws plus toucans/araçaris. Best at early morning / late afternoon","commission":"AOR → licensed reserve access"},{"name":"Night float","si_tag":"wildlife","tier":"comfort","source":"https://www.livemoretravelmore.com/things-to-do-in-bonito-brazil/","si":"wildlife","commission":"licensed-agency voucher"},{"name":"Pantanal wildlife extension (gateway)","si_tag":"wildlife","tier":"comfort","source":"https://www.aventuradobrasil.com/blog/bonito-brazils-natural-gem-of-crystal-clear-rivers-and-hidden-caves/","hook":"The high-value pairing: Bonito''s clear water + Pantanal''s unmatched wildlife density. Same regional DMC can carry both","si":"wildlife","blurb":"The high-value pairing: Bonito''s clear water + Pantanal''s unmatched wildlife density. Same regional DMC can carry both","commission":"AOR combo mandate (Bonito + Pantanal)"}],"faq":[{"q":"When is the best time to snorkel Bonito''s crystal rivers?","a":"The dry season — roughly June–September, within the broader May–September dry window — delivers the clearest, most predictable water, because the winter rains that raise rivers and drop visibility have stopped; daily visitor slots are physically capped, so book at least a week ahead in high season (July–September).","source":"lonelyplanet.com, 2026-07-07","si_tag":"expedition"},{"q":"Can you actually see wild macaws near Bonito?","a":"Yes — Buraco das Araras, South America''s largest sinkhole (~500 m circumference, ~100 m deep) near Jardim, is a heavily regulated sanctuary for red-and-green macaws plus toucans and araçaris, best viewed at early morning or late afternoon on a guided visit.","source":"en.wikipedia.org, 2026-07-07","si_tag":"wildlife"},{"q":"Is Bonito a good honeymoon destination?","a":"Yes, as a slow water-and-forest romance add-on rather than a luxury-ceremony market: the top of the market is the 4-star Zagaia Eco Resort — grounds, pools and full recreation — with boutique eco-pousadas filling the couples tier, so set expectations to best-in-region eco, not five-star.","source":"evendo.com, 2026-07-07","si_tag":"romance"},{"q":"Is the Abismo Anhumas cave rappel dangerous?","a":"It is a serious, technical activity run safely under a guided-mandatory system: a 72 m harness rappel on electric devices into a cavern lake (~18°C water, submerged cones to ~20 m), capped at a maximum of 16 people per day with certified monitors — never a free-climb and never sold unguided.","source":"explore-share.com, 2026-07-07","si_tag":"safety"},{"q":"What''s the real risk to plan for in Bonito?","a":"Sell-outs, not danger: because every attraction runs on a licensed-agency voucher with hard daily caps, marquee tours like Rio da Prata and Rio Sucuri can sell out weeks ahead of time, so the booking *is* the reservation — reserve the voucher itinerary, not just the room.","source":"en.wikivoyage.org, 2026-07-07","si_tag":"safety"}],"seo":{"meta_title":"Bonito, Brazil: Crystal-River Snorkeling, Caves & the Pantanal Gateway — TravelWell","jsonld_type":"TouristDestination","author_byline":"By David McCallister — commercial pilot, 56 countries","freshness":"2026-07-07","search_language":"pt-BR","local_keywords":["Bonito MS o que fazer","Rio da Prata flutuação","Gruta do Lago Azul","melhor época para ir a Bonito","Abismo Anhumas rapel","Boca da Onça cachoeira","Bonito e Pantanal roteiro","Buraco das Araras Jardim"],"hreflang":["en","pt-BR"],"primary_keyword":"Bonito"},"booking":null,"si_checklist_25":null,"sis_present":[{"si":"wildlife","status":"live"}],"ultra":[{"name":"Zagaia Eco Resort","positioning":"4-star Bonito ceiling","earning":"room commission","mor":"DMC/AOR","tier":"Premium (regional ceiling)"},{"name":"Santa Esmeralda","positioning":"upper-boutique eco-pousada","earning":"room commission / bedbank","mor":"AOR/bedbank","tier":"Premium-lite"},{"name":"Boutique eco-pousadas (curated)","positioning":"design-forward small pousadas — premier eco ceiling, not 5-star","earning":"room commission","mor":"AOR/bedbank","tier":"Mid → Premium-lite"}],"source_verified":null,"hero":{"query":"Bonito, Brazil, Brazil"},"geo":{"lat":-21.1261,"lng":-56.4514}}'::jsonb, 13),
  ('buenos-aires-argentina', '10S', 'Buenos Aires, Argentina', 'Argentina', 'Leather and silk, beef and fire', 'live', 'verified', 'paris', 'Buenos Aires & The Pampas', '{"romance","culture","culinary"}', '{}', '{"essential","comfort","premier","luxury","ultra"}', null, null, '{"key_facts":["US State Dept Level 1 - Exercise Normal Precautions (advisory dated 2026-05-20); Rosario is a city-level L2 exception, not on a BA itinerary.","Best experience = spring/fall shoulder (Oct-Nov, Mar-Apr); November brings jacaranda bloom + the Argentine Open Polo.","Signature BA experiences: milonga tango, puerta-cerrada (closed-door) asado, Malbec tasting, Recoleta Cemetery (Evita), Teatro Colon.","Day-trip belt: Tigre Delta (~1 hr), San Antonio de Areco estancia (~1.5 hr), Colonia/Uruguay ferry across the Rio de la Plata.","Petty crime is theft-by-distraction, not force (motochorros, ~90% at traffic lights); La Boca daytime-and-Caminito only; tap water potable."],"safety":{"emergency":"911","police":"101","ambulance":"107","fire":"100","us_embassy_ba":"+54 11 5777-4354","advisory_level":"L1","book_enabled":true,"bin":"freely bookable (L1)","consent_flow":false,"air_access_verified":{"international":"EZE (Ezeiza / Ministro Pistarini)","domestic":"AEP (Aeroparque Jorge Newbery)"},"water":"potable","trauma_path":"BA private hospitals excellent; stabilize locally then US medevac for catastrophic cases","fcdo":{"posture":"1","quotes":[],"url":"https://www.gov.uk/foreign-travel-advice/argentina","read":"2026-08-19","page_updated":"2026-05-07T17:26:11+01:00"}},"timing":{"peak_experience":"Oct-Nov and Mar-Apr (shoulder — best weather/crowds)","peak_volume":"Dec-Feb (austral summer — hot/humid, least comfortable)","inflection_curve_start":"loads ahead of each shoulder window + Nov events","fire_date":"curve-start minus 1-2 weeks (~early Sep for Oct-Nov; ~January for Mar-Apr); November premium = 3-6 months lead","events":[{"name":"Argentine Open Polo Championship","month":"November","venue":"Campo Argentino de Polo, Palermo"},{"name":"Tango BA Festival y Mundial","month":"August (austral winter — NOT November)"}],"low_season":"Jun-Aug (winter; occupancy low ~Apr-Jun — value window)"},"jewels":[{"name":"Private milonga tango night","si_tag":"romance","tier":"comfort","source":"https://www.getyourguide.com/buenos-aires-l1/","hook":"The real social tango — a couple''s night at an authentic milonga beats any tourist stage show for a honeymoon","si":"romance","blurb":"The real social tango — a couple''s night at an authentic milonga beats any tourist stage show for a honeymoon","commission":"activities affiliate / DMC private experience"},{"name":"Recoleta jacarandas + Recoleta Cemetery (Evita tomb)","si_tag":"RHN / Culture","tier":"essential","source":"https://www.buenosairesfreewalks.com/what-to-do/grave-of-evita-peron/","timing":"year-round","timing_type":"ALWAYS-ON","hook":"A November walk through Recoleta''s lilac-blossom boulevards into the most famous cemetery in the Americas","si":"RHN / Culture","blurb":"A November walk through Recoleta''s lilac-blossom boulevards into the most famous cemetery in the Americas","when":"year-round","commission":"DMC/guide (entry non-commissionable)"},{"name":"Closed-door (puerta cerrada) asado — Fogon Asado","si_tag":"culinary","tier":"premier","source":"https://www.getyourguide.com/buenos-aires-l1/buenos-aires-8-course-argentine-bbq-at-fogon-asado-t235877/","hook":"The most intimate, most Porteño dinner in the city — see Culinary below; sells beautifully as a honeymoon night","si":"culinary","blurb":"The most intimate, most Porteño dinner in the city — see Culinary below; sells beautifully as a honeymoon night","commission":"activities affiliate / DMC"},{"name":"Casa Saltshaker puerta cerrada + Malbec flight","si_tag":"culinary","tier":"comfort","source":"https://theculturetrip.com/south-america/argentina/articles/the-best-closed-door-restaurants-in-buenos-aires","hook":"Intimate shared-table five-course dinners with Malbec-vs-Patagonian-pinot flights — one of the city''s oldest supper clubs","si":"culinary","blurb":"Intimate shared-table five-course dinners with Malbec-vs-Patagonian-pinot flights — one of the city''s oldest supper clubs","commission":"DMC-brokered / direct"},{"name":"Malbec / Argentine-wine tasting","si_tag":"culinary","tier":"comfort","source":"https://theculturetrip.com/south-america/argentina/articles/the-best-closed-door-restaurants-in-buenos-aires","hook":"Guided verticals of Mendoza Malbec, Patagonian pinot, and high-altitude Salta torrontés — in-city tasting rooms or a DMC-curated flight","si":"culinary","blurb":"Guided verticals of Mendoza Malbec, Patagonian pinot, and high-altitude Salta torrontés — in-city tasting rooms or a DMC-curated flight","commission":"DMC / activities affiliate"},{"name":"San Telmo Sunday feria (Calle Defensa)","si_tag":"Culinary / Culture","tier":"essential","source":"https://en.wikivoyage.org/wiki/Buenos_Aires","hook":"The Sunday street market and antiques fair — empanadas, choripán, street tango, and browsing","si":"Culinary / Culture","blurb":"The Sunday street market and antiques fair — empanadas, choripán, street tango, and browsing","commission":"content-led; guided-tour affiliate"},{"name":"MALBA — Latin American art museum","si_tag":"culture","tier":"essential","source":"https://en.wikivoyage.org/wiki/Buenos_Aires/Palermo_%26_Recoleta","timing":"year-round","timing_type":"ALWAYS-ON","si":"culture","when":"year-round","commission":"admission non-commissionable; DMC guided visit"},{"name":"Teatro Colon guided tour / opera night","si_tag":"Culture / RHN","tier":"essential","source":"https://turismo.buenosaires.gob.ar/en","si":"Culture / RHN","commission":"box-office non-commissionable; DMC package"},{"name":"Palermo Soho boutiques","si_tag":"culture","tier":"comfort","source":"https://en.wikivoyage.org/wiki/Buenos_Aires/Palermo_%26_Recoleta","hook":"High-end Argentine fashion and leather boutiques on cobblestone streets — the \"silk\" half of BA''s soul","si":"culture","blurb":"High-end Argentine fashion and leather boutiques on cobblestone streets — the \"silk\" half of BA''s soul","commission":"content-led; concierge personal-shopper"},{"name":"La Boca / Caminito (daytime only)","si_tag":"culture","tier":"essential","source":"https://solsalute.com/blog/is-buenos-aires-safe-for-tourists/","hook":"The painted tin tenements, birthplace of tango and of Boca Juniors — a guided daytime visit only","si":"culture","blurb":"The painted tin tenements, birthplace of tango and of Boca Juniors — a guided daytime visit only","commission":"guided-tour affiliate / DMC"},{"name":"Tigre Delta day","si_tag":"culture","tier":"essential","source":"https://luxurylatinamerica.com/blog/2023/03/13/day-trips-from-buenos-aires/","hook":"An hour north, the Paraná Delta''s maze of channels and stilt-houses","si":"culture","blurb":"An hour north, the Paraná Delta''s maze of channels and stilt-houses","commission":"activities affiliate / DMC day-tour"},{"name":"Pampas estancia day — San Antonio de Areco (gaucho)","si_tag":"culture","tier":"comfort","source":"https://solsalute.com/blog/best-buenos-aires-day-trips/","hook":"~1½ hrs out onto the grasslands to a working ranch: horseback, all-afternoon asado, folklore, and gaucho tradition","si":"culture","blurb":"~1½ hrs out onto the grasslands to a working ranch: horseback, all-afternoon asado, folklore, and gaucho tradition","commission":"DMC / MoR estancia booking"},{"name":"Argentine Open Polo (November, Palermo)","si_tag":"culture","tier":"premier","source":"https://www.theaircharterjournal.com/air-charter-journal/argentine-polo-open-2025","hook":"The world''s most prestigious polo championship, at the \"Cathedral of Polo\" — grandstand and hospitality seats are a marquee November draw","si":"culture","blurb":"The world''s most prestigious polo championship, at the \"Cathedral of Polo\" — grandstand and hospitality seats are a marquee November draw","commission":"DMC / hospitality-package MoR"},{"name":"Colonia del Sacramento day trip (Uruguay)","si_tag":"culture","tier":"comfort","source":"https://luxurylatinamerica.com/blog/2023/03/13/day-trips-from-buenos-aires/","hook":"Ferry across the Río de la Plata to a UNESCO colonial town — the calm counterpoint to BA","si":"culture","blurb":"Ferry across the Río de la Plata to a UNESCO colonial town — the calm counterpoint to BA","commission":"ferry affiliate + DMC day-tour"}],"faq":[{"q":"When is the best time to visit Buenos Aires for a honeymoon?","a":"The spring and fall shoulders — October–November and March–April — are the sweet spot, with mild 18–26 °C days and thinner crowds than the hot, humid summer. November is the standout: the jacarandas bloom lilac across Recoleta''s boulevards and the Argentine Open Polo fills Palermo, so treat November premium beds as a 3–6 month advance book.","source":"lonelyplanet.com, Accessed 2026-07-07","si_tag":"romance"},{"q":"What are the must-see cultural sites in Buenos Aires?","a":"Start with Recoleta Cemetery — 6,400+ statues and crypts, including Evita Perón''s tomb, with free Spanish guided tours Tue–Sun — then Teatro Colón, one of the great opera houses of the world, and a daytime visit to La Boca''s Caminito, birthplace of tango. San Telmo''s Sunday feria on Calle Defensa rounds out the heritage circuit.","source":"buenosairesfreewalks.com, Accessed 2026-07-07","si_tag":"culture"},{"q":"What is a puerta cerrada (closed-door) restaurant?","a":"They are secret chef''s-home supper clubs, a Porteño institution. Fogón Asado runs a Michelin-recommended 9-course asado tasting for ~35 guests with optional Argentine wine pairings, while Casa Saltshaker (est. 2005) does intimate shared-table five-course dinners with Malbec-vs-Patagonian-pinot flights — one of the city''s oldest such houses.","source":"theculturetrip.com, Accessed 2026-07-07","si_tag":"culinary"},{"q":"What''s the real risk to plan for in Buenos Aires?","a":"Snatch-and-grab theft, not violence. BA''s characteristic street crime is motochorros (motorcycle thieves) and distraction scams, with roughly 90% of motochorro snatchings happening at traffic lights; keep your phone off café-table edges and use vetted radio-taxi or ride-apps. La Boca is daytime-and-Caminito only — arrive by taxi and leave before dark.","source":"secretsofbuenosaires.com, Accessed 2026-07-07","si_tag":"safety"},{"q":"Do I need travel insurance for Argentina?","a":"Treat it as required and always buy it. Under Decree 366/2025, effective 2025-07-01, non-resident travelers were required to carry travel medical insurance covering emergency care, hospitalization, evacuation and repatriation, with airlines confirming at check-in. One December-2025 secondary source reported the rule may have been suspended or modified (unverified and conflicting), so verify current enforcement at booking.","source":"globalrescue.com, Accessed 2026-07-07","si_tag":"safety"}],"seo":{"meta_title":"Buenos Aires Travel Guide — Tango, Steak & Boutique Hotels | TravelWell","jsonld_type":"TouristDestination","author_byline":"By David McCallister — commercial pilot, 56 countries","freshness":"2026-07-07","search_language":"es-AR","long_tail_en":["things to do in Buenos Aires","best tango show Buenos Aires","closed-door restaurants Buenos Aires","Buenos Aires honeymoon","best time to visit Buenos Aires","Recoleta cemetery Evita","Tigre Delta day trip","San Antonio de Areco estancia","Buenos Aires luxury hotels","is Buenos Aires safe"],"local_keywords":["qué hacer en Buenos Aires","show de tango Buenos Aires","mejores parrillas Buenos Aires","puertas cerradas Buenos Aires","Cementerio de la Recoleta Evita","estancia San Antonio de Areco","escapada al Delta del Tigre","hoteles de lujo Buenos Aires","Abierto Argentino de Polo","mejor época para visitar Buenos Aires"],"hreflang":["en","es-AR"]},"booking":null,"si_checklist_25":null,"sis_present":null,"ultra":[{"name":"Four Seasons Hotel Buenos Aires + La Mansion","barrio":"Recoleta","tier":"ultra","earning":"FS Preferred Partner / Virtuoso — commission + amenities (UNVERIFIED %)"},{"name":"Alvear Palace Hotel","barrio":"Recoleta","tier":"ultra","earning":"Virtuoso / LHW — commission + amenities (UNVERIFIED %)"},{"name":"Palacio Duhau — Park Hyatt Buenos Aires","barrio":"Recoleta","tier":"ultra","earning":"Hyatt Prive / Virtuoso — commission + amenities (UNVERIFIED %)"},{"name":"Faena Hotel Buenos Aires","barrio":"Puerto Madero","tier":"ultra","earning":"Virtuoso / brand luxury — commission + amenities (UNVERIFIED %)"}],"source_verified":null,"hero":{"query":"Buenos Aires, Argentina, Argentina"},"geo":{"lat":-34.6037,"lng":-58.3816}}'::jsonb, 14),
  ('cabo-pulmo-mexico', '10S', 'Cabo Pulmo', 'Mexico', 'The Sea of Cortez, recovered', 'live', 'verified', 'mountainValley', 'Baja California Sur (Los Cabos & La Paz)', '{"expedition","diveglobal"}', '{}', '{"essential","premier"}', null, null, '{"key_facts":["Federally protected National Marine Park since June 5, 1995; ~71 km2 fully protected (Source: en.wikipedia.org/wiki/Cabo_Pulmo_National_Park, 2026-07-04)","463% total fish-biomass increase, ~11x top-predator jump by 2009 — most successful no-take recovery measured (Source: ocean.si.edu, 2026-07-04)","Only living hard-coral reef in the Sea of Cortez; UNESCO WHS 2005, Ramsar 2008 (Source: en.wikipedia.org, 2026-07-04)","CONANP no-take rules: guide-led 6:1, no touching, gloves banned, licensed pangas only (Source: mexicotraveladventure.com, 2026-07-04)","Off-grid village; ~2-3 h drive north of SJD / Los Cabos; eco-cabañas only, no luxury hotels (Source: sallysees.com, 2026-07-04)"],"safety":{"emergency":"911","nearest_trauma":"Cabo San Lucas / San Jose del Cabo (Los Cabos), ~2-3 h by road; La Paz alternative","advisory_level":"L2","advisory_note":"Baja California Sur US Level 2 (Exercise Increased Caution), May 29, 2026 — freely bookable, disclose L2, no hold","malaria":"none","dengue":"present in Baja California Sur; use repellent","water":"bottled/purified","hurricane":"May 15-Nov 30, peak Aug-Oct","remote_medevac":"off-grid; no chamber/hospital in village; multi-hour ground evac to Los Cabos","fcdo":{"posture":"AREA-RESTRICTED","quotes":[{"form":"against all but essential travel","text":"advises against all but essential travel State of Baja California FCDO advises against all but essential travel to the city of Tijuana, except: airside transit through Tijuana airport the Cross Border Xpress bridge from the airport linking terminals across the Mexican-US border the federal toll road 1D and Via Rápida through Tijuana to the border FCDO advises against all but essential travel to the city of Tecate in Baja California, including roads between Tijuana and Tecate."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Chihuahua, except: the city of Chihuahua the border crossing in Ciudad Juárez (accessed by federal toll road 45) federal toll road 45D connecting the cities of Chihuahua and Ciudad Juárez the Copper Canyon rail route to and from Chihuahua and towns immediately on this route including Creel the road from Creel via San Juanito to San Pedro state highway 16 from San Pedro to Chihuahua State of Sinaloa FCDO advises against all but essential travel to the state of Sinaloa, except: the cities of Los Mochis and Mazatlán road 32 that runs between El Fuerte and Los Mochis the 15D federal toll road that runs the length of the state the Copper Canyon rail route to and from Los Mochis, El Fuerte and the towns immediately on this route State of Tamaulipas FCDO advises against all but essential travel to the state of Tamaulipas, except: the border crossing at Nuevo Laredo accessed by federal toll road 85D from Monterrey federal highways 80, 81 and 85 between Tampico, Ciudad de Victoria and Magueyes, and the entire area of Tamaulipas south of these highways State of Zacatecas FCDO advises against all but essential travel to the state of Zacatecas."},{"form":"against all but essential travel","text":"advises against all but essential travel to the areas south-west of road 45D."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Michoacán, except the: city of Morelia accessed by federal toll roads 15D, 126 and 43; and the federal toll road 48D between the city of Morelia and the General Francisco Mujica airport town of Pátzcuaro accessed by federal toll roads 14D and 15 from Morelia, and boat trips out to islands on Lake Pátzcuaro Federal Highway 15D State of Jalisco FCDO advises against all but essential travel to the areas south and south-west of Lake Chapala to the border with the state of Colima."},{"form":"against all but essential travel","text":"advises against all but essential travel to the northern municipalities of: Bolaños Chimaltitán Colotlán Hostotipaquillo Huejúcar Huequilla el Alto Mezquitic San Martin de Bolaños Santa Maria de los Ángeles Totatiche Villa Guerrero State of Colima FCDO advises against all but essential travel to the state of Colima, except the city of Manzanillo accessed by sea or air via the Manzanillo-Costalegre International Airport, and direct travel via road 200 from the airport to Manzanillo."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Guerrero, except the town of Zihuatanejo/Ixtapa accessed by air."},{"form":"against all but essential travel","text":"advises against all but essential travel to within 40km of the Guatemalan border between the Pacific Coast up to and including the border crossing at Gracias a Dio."},{"form":"against all but essential travel","text":"advises against all but essential travel on Federal Highway 199 (Carretera Federal 199) between Rancho Nuevo (just outside San Cristobal de las Casas) and the Chancalá junction just outside Palenque (where Federal Highway 199 meets Federal Highway 307)."},{"form":"against all but essential travel","text":"advises against all but essential travel to the city of Acapulco."},{"form":"against all but essential travel","text":"advises against all but essential travel to the city of Tijuana, except: airside transit through Tijuana airport the Cross Border Xpress bridge from the airport linking terminals across the Mexican-US border the federal toll road 1D and Via Rápida through Tijuana to the border FCDO advises against all but essential travel to the city of Tecate in Baja California, including roads between Tijuana and Tecate."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Chihuahua, except: the city of Chihuahua the border crossing in Ciudad Juárez (accessed by federal toll road 45) federal toll road 45D connecting the cities of Chihuahua and Ciudad Juárez the Copper Canyon rail route to and from Chihuahua and towns immediately on this route including Creel the road from Creel via San Juanito to San Pedro state highway 16 from San Pedro to Chihuahua There are high levels of organised crime activity, particularly human and drugs trafficking."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Sinaloa, except: the cities of Los Mochis and Mazatlán road 32 that runs between El Fuerte and Los Mochis the 15D federal toll road that runs the length of the state the Copper Canyon rail route to and from Los Mochis, El Fuerte and the towns immediately on this route Armed robbery and vehicle theft has happened in El Fuerte."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Tamaulipas, except: the border crossing at Nuevo Laredo accessed from Monterrey by federal toll road 85D – you should travel during daylight hours federal highways 80, 81 and 85 between Tampico, Ciudad de Victoria and Magueyes, and the entire area of Tamaulipas south of these highways Tamaulipas is dangerous due to the presence of many organised crime groups who fight for control of drug trafficking routes."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Zacatecas."},{"form":"against all but essential travel","text":"advises against all but essential travel to the areas south-west of the road 45D."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Michoacán, except the: city of Morelia accessed by federal toll roads 15D, 126 and 43; and the federal toll road 48D between the city of Morelia and the General Francisco Mujica airport town of Pátzcuaro accessed by federal toll roads 14D and 15 from Morelia, and boat trips out to islands on Lake Pátzcuaro federal highway 15D Michoacán is one of Mexico’s most violent states with high levels of organised crime and very little security presence."},{"form":"against all but essential travel","text":"advises against all but essential travel to the areas south and south-west of Lake Chapala to the border state of Colima, specifically the municipalities of: Acatlán de Juárez Amacueca Ameca Atemajac de Brizuela Atengo Atenguillo Atoyac Autlán de Navarro Ayutla Casimiro Castillo Chiquilistlán Cocula Cuautitlán de García Barragán Cuautla Ejutla El Grullo El Limón Gómez Farias Guachinango Juchitlán Mixtlán San Gabriel San Marcos San Martín Hidalgo Sayula Tapalpa Techaluta de Montenegro Tecolotlán Tenamaxtlán Teocuitatlán de Corona Tolimán Tonaya Tuxcacuesco Tuxcueca Unión de Tula Villa Corona Villa Purificación Zacoalco de Torres Zapotitlán de Vadill Zapotlán el Grande FCDO advises against all but essential travel to the northern municipalities of: Bolaños Chimaltitán Colotlán Hostotipaquillo Huejúcar Huequilla el Alto Mezquitic San Martin de Bolaños Santa Maria de los Ángeles Totatiche Villa Guerrero This is due to inaccessibility for security forces, lack of state control, drugs cultivation and high levels of violence between rival criminal groups."},{"form":"against all but essential travel","text":"advises against all but essential travel to the whole state of Colima, except the city of Manzanillo accessed by sea or by air via Manzanillo-Costalegre International Airport, and direct travel via road 200 from the airport to Manzanillo."}],"url":"https://www.gov.uk/foreign-travel-advice/mexico","read":"2026-08-19","page_updated":"2026-07-16T16:08:09+01:00"}},"timing":{"peak":"Jul-Nov (best visibility, bull-shark aggregation)","shoulder":"Apr-Jun, late fall","green":"Dec-Feb (coolest water, wind days)","booking_window_lead_time":"2-4 months (capped dive slots + tiny bed inventory)","out_of_season_fill":"winter dive-and-stay packages; East Cape / Los Cabos day-trip combos","holiday_event_peaks":["US/Canada summer holidays","Los Cabos Dec-Apr high-season spillover"],"campaign_start_trigger":"late spring for summer-fall dive peak; Los Cabos winter high season for day-trip capture"},"jewels":[{"si_tag":"expedition","status":"live","tier":"essential","commission":"operator agreement","name":"Pulmo reef recovery dive","si":"expedition"},{"si_tag":"expedition","status":"live","tier":"premier","commission":"operator agreement","name":"Bull-shark aggregation dive","si":"expedition"},{"si_tag":"expedition","status":"live","tier":"essential","commission":"operator + DMC","name":"Protected-reef snorkel","si":"expedition"},{"si_tag":"expedition","status":"live","tier":"premier","commission":"operator agreement","name":"Sea-lion / offshore pinnacle dives","si":"expedition"},{"si_tag":"diveglobal","status":"future","tier":"premier","commission":"operator; stay direct","name":"Multi-day Cabo Pulmo dive-and-stay","si":"diveglobal"}],"faq":[{"q":"Is Cabo Pulmo worth diving, and what will I see?","a":"Yes — it is arguably the Sea of Cortez''s best dive, because protection worked: total fish biomass rebounded 463% by 2009 on the Gulf''s only living hard-coral reef. Expect schooling jacks, groupers and rays, and in warm summer–fall water a bull-shark aggregation.","source":"ocean.si.edu / divearoo.com, 2026-07-04","si_tag":"expedition"},{"q":"Do I need to be certified, and can non-divers go?","a":"You dive within your card with a mandatory park guide (max 6 divers each), and non-divers can snorkel the same no-take reef. The rules are strict — no gloves, no touching, licensed pangas only — and enforced; break them and you can be pulled from the water.","source":"mexicotraveladventure.com, 2026-07-04","si_tag":"diveglobal"},{"q":"Can couples make a romantic escape of Cabo Pulmo?","a":"Only if \"romantic\" means off-grid and simple — there is no resort or spa layer. Lodging is solar eco-cabañas and a tiny villa cluster (~5 villas), which suits low-key couples; anyone wanting branded luxury bases in Los Cabos or the East Cape and day-trips in.","source":"sallysees.com / cabopulmo.com, 2026-07-04","si_tag":"romance"},{"q":"Is diving here dangerous — what''s the real risk?","a":"The gatekeeper is medevac distance, not the diving itself. Cabo Pulmo is off-grid with no chamber or hospital in the village; the nearest recompression chamber and trauma care are ~2–3 hours away in Los Cabos, so dive conservatively, carry DAN cover, and observe 18–24 h no-fly before an SJD departure.","source":"sssnetwork.com / dan.org, 2026-07-04","si_tag":"safety"}],"seo":{"meta_title":"Cabo Pulmo Diving — Sea of Cortez No-Take Reef | TravelWell.World","meta_description":"Dive Cabo Pulmo, the most-recovered no-take marine reserve in the Sea of Cortez. Guided park dives, no-touch rules, eco-cabaña stays, Los Cabos gateway logistics.","primary_keywords":["Cabo Pulmo diving","Cabo Pulmo National Park","Cabo Pulmo snorkeling","Sea of Cortez reef"],"long_tail":["best time to dive Cabo Pulmo","Cabo Pulmo bull shark season","how to get to Cabo Pulmo from Los Cabos","Cabo Pulmo eco cabañas"],"search_language":"es-MX","local_keywords":["buceo Cabo Pulmo","Parque Nacional Cabo Pulmo","arrecife de coral Mar de Cortes","snorkel Cabo Pulmo","reserva marina sin pesca","cabanas ecologicas Cabo Pulmo"],"hreflang":["en","es-MX"],"jsonld_type":"TouristAttraction","author_byline":"By David McCallister — commercial pilot, 56 countries","content_freshness":"2026-07-04"},"booking":null,"si_checklist_25":null,"sis_present":["expedition","diveglobal"],"ultra":[{"what":"Four Seasons Los Cabos at Costa Palmas / Amanvari (East Cape, Los Cabos) as luxury base for a Cabo Pulmo dive charter","why_ultra":"largest swimmable beach + only private marina in Los Cabos; Amanvari is first Aman in Mexico (spring 2026)","earning":"on application / via host-Virtuoso","virtuoso_value_add":"resort credit, upgrade, breakfast; private guide for Pulmo run","mor":"resale via host-Virtuoso only; Cabo Pulmo itself is NOT an ultra stay — nearest ultra is Los Cabos"}],"source_verified":"2026-07-04","hero":{"query":"Cabo Pulmo, Mexico"},"geo":{"lat":23.4433,"lng":-109.4283}}'::jsonb, 15),
